// Generic generator: node docs/jee-build/gen.mjs <key>
// Reads docs/jee-build/<key>-data.mjs, writes docs/<key>_seed.sql with
// {{TOKEN}} UUID placeholders. Run scripts/fill-seed-uuids.mjs on the
// output afterward. Same process used for HAL/AWS SAA/Security+/CCS/CPT/
// NEET, extended here to support a SECOND question shape: numeric-entry
// (answer_type = "numeric", e.g. JEE Main's Numerical Value Questions) —
// see docs/add-numeric-answer-type.sql, which MUST be applied before any
// numeric-type paper generated by this script can be seeded.
//
// Two question shapes in a data file's SECTIONS[].questions array:
//   MCQ:     { topic, stem, options: [4 strings], correct: 0-3, explanation }
//   Numeric: { topic, stem, answerType: "numeric", numericAnswer: <number>, explanation }
// gen.mjs branches per-question on whether answerType === "numeric" —
// a single section can freely mix both shapes (e.g. JEE Main's Section A
// MCQs and Section B NVQs within the same subject).
import { writeFileSync } from "node:fs";

const key = process.argv[2];
if (!key) { console.error("Usage: node docs/jee-build/gen.mjs <key>"); process.exit(1); }

const { PAPER, SECTIONS, HEADER_LABEL } = await import(`./${key}-data.mjs`);

function esc(s) {
  return String(s).replace(/'/g, "''");
}

const lines = [];
lines.push(`-- ============================================================`);
lines.push(`-- ${HEADER_LABEL}`);
lines.push(`-- Full-Length Practice Paper (${PAPER.questionCount} questions, ${PAPER.timeLimitMinutes} minutes)`);
lines.push(`-- Marking: +${PAPER.positiveMarks} correct / -${PAPER.negativeMarks} incorrect`);
lines.push(`-- Run this AFTER docs/add-numeric-answer-type.sql.`);
lines.push(`-- ============================================================`);
lines.push(``);

const paperId = "{{PAPER}}";
lines.push(`-- ---------- Paper ----------`);
lines.push(
  `INSERT INTO question_papers (id, slug, title, exam_type, focus_tags, question_count, difficulty, is_premium, sort_order, time_limit_minutes, positive_marks, negative_marks)`
);
lines.push(
  `VALUES ('${paperId}', '${PAPER.slug}', '${esc(PAPER.title)}', '${PAPER.examType}', ARRAY[${PAPER.focusTags.map((t) => `'${esc(t)}'`).join(", ")}]::TEXT[], ${PAPER.questionCount}, '${PAPER.difficulty}', true, ${PAPER.sortOrder}, ${PAPER.timeLimitMinutes}, ${PAPER.positiveMarks}, ${PAPER.negativeMarks});`
);
lines.push(``);

let sortOrder = 0;
let mcqCount = 0;
let numericCount = 0;
const allStems = [];
const distractorFlags = [];
const RISKY_PHRASES = /\bcannot\b|\bnever\b|\bis not possible\b|\bno such\b|\bimpossible\b|\bunder no circumstances\b/i;

for (const section of SECTIONS) {
  lines.push(`-- ── Section: ${section.name} (${section.questions.length} questions) — ${section.sourceNote} ──`);
  lines.push(``);
  for (const q of section.questions) {
    sortOrder += 1;
    allStems.push(q.stem);
    const qId = `{{Q${sortOrder}}}`;
    const subjectVal = section.subject ? `'${esc(section.subject)}'` : "NULL";
    const topicVal = q.topic ? `'${esc(q.topic)}'` : "NULL";
    const isNumeric = q.answerType === "numeric";
    const answerTypeVal = isNumeric ? "numeric" : "mcq";

    lines.push(`INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)`);
    lines.push(`VALUES ('${qId}', '${paperId}', ${sortOrder}, '${esc(q.stem)}', ${subjectVal}, ${topicVal}, '${answerTypeVal}');`);

    if (isNumeric) {
      numericCount += 1;
      if (typeof q.numericAnswer !== "number" || !Number.isFinite(q.numericAnswer)) {
        console.log("BAD NUMERIC ANSWER:", q.stem, "->", q.numericAnswer);
      }
      lines.push(`INSERT INTO question_answers (question_id, correct_numeric_answer, explanation, source_note)`);
      lines.push(`VALUES ('${qId}', ${q.numericAnswer}, '${esc(q.explanation)}', '${esc(section.sourceNote)}');`);
    } else {
      mcqCount += 1;
      const correctText = q.options[q.correct];
      if (RISKY_PHRASES.test(correctText)) {
        distractorFlags.push({ sortOrder, stem: q.stem, correctText });
      }
      const optionIds = q.options.map((_, i) => `{{Q${sortOrder}_OPT${i}}}`);
      q.options.forEach((opt, i) => {
        lines.push(
          `INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('${optionIds[i]}', '${qId}', ${i}, '${esc(opt)}');`
        );
      });
      lines.push(`INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)`);
      lines.push(
        `VALUES ('${qId}', '${optionIds[q.correct]}', '${esc(q.explanation)}', '${esc(section.sourceNote)}');`
      );
    }
    lines.push(``);
  }
}

const outPath = `d:/synfracore/docs/${key}_seed.sql`;
writeFileSync(outPath, lines.join("\n"), "utf8");

const dupStems = allStems.filter((s, i) => allStems.indexOf(s) !== i);
console.log(`Total questions written: ${sortOrder} (expected ${PAPER.questionCount}) -- MCQ: ${mcqCount}, Numeric: ${numericCount}`);
console.log(`Duplicate question stems (within paper): ${dupStems.length}`, dupStems);
for (const section of SECTIONS) {
  if (!section.subject) console.log("MISSING SECTION SUBJECT:", section.name);
  for (const q of section.questions) {
    if (q.answerType === "numeric") {
      if (!q.topic) console.log("MISSING TOPIC:", q.stem);
    } else {
      if (!q.options || q.options.length !== 4) console.log("BAD OPTION COUNT:", q.stem);
      if (q.correct < 0 || q.correct > 3) console.log("BAD CORRECT INDEX:", q.stem);
      if (!q.topic) console.log("MISSING TOPIC:", q.stem);
    }
  }
}
console.log(`Distractor-language sanity-scan flags on the CORRECT answer (MCQ only, manually verify each, don't auto-fix): ${distractorFlags.length}`);
for (const f of distractorFlags) console.log("  FLAG Q" + f.sortOrder + ":", f.stem, "-> correct:", f.correctText);

const written = lines.join("\n");
let quoteIssues = 0;
written.split("\n").forEach((line, i) => {
  if (line.trim().startsWith("--")) return;
  const stripped = line.replace(/''/g, "");
  const count = (stripped.match(/'/g) || []).length;
  if (count % 2 !== 0) { quoteIssues++; console.log(`QUOTE IMBALANCE at generated line ${i + 1}:`, line); }
});
console.log(`Quote-balance issues: ${quoteIssues}`);

const subjectCounts = {};
for (const section of SECTIONS) subjectCounts[section.subject] = (subjectCounts[section.subject] || 0) + section.questions.length;
console.log("Subject counts:", subjectCounts);

console.log(`Done -> ${outPath}`);
